load('data3.mat');
G3 = bj(data3, [5, 5, 5, 5, 1]);
G3_c = d2c(G3);
[A,B,C,D] = ssdata(G3_c);

% Define variables
n = size(A,1); m = size(B,2); p = size(C,1);
X = sdpvar(n,n,'symmetric');
Y = sdpvar(m,n,'full');
Z1 = sdpvar(p,p,'symmetric');
Z2 = sdpvar(m,m,'symmetric');

% LMI constraints using Schur and bounded real lemmas
epsilon = 1e-6;
Constraints = [A*X + X*A' - B*Y - Y'*B' <= -epsilon*eye(n), ...
              [Z1 C*X; X*C' X] >= 0, ...
              [Z2 Y; Y' X] >= 0, ...
              X >= epsilon*eye(n)];

% Objective: minimize trace(Z1) + trace(Z2)
Objective = trace(Z1) + trace(Z2);

% Solve LMI
options = sdpsettings('solver','sedumi','verbose',0);
sol = optimize(Constraints, Objective, options);

% Extract controller
X_opt = value(X);
Y_opt = value(Y);
K = Y_opt/X_opt;

% Closed-loop system
sys_cl = ss(A-B*K,B,C,D);

% Compare with LQR
Q = C'*C + 1e-3*eye(n);
R = eye(m);
[K_lqr,~,~] = lqr(A,B,Q,R);
sys_cl_lqr = ss(A-B*K_lqr,B,C,D);

% Plot step responses
figure; 
step(sys_cl,'b', sys_cl_lqr,'r--');
legend('H2 Controller','LQR Controller');
grid on;

% Display norms
h2_norm = norm(h2norm(sys_cl));
h2_norm_lqr = norm(h2norm(sys_cl_lqr));
