    def process_single_pdf(self, file_path: str) -> Tuple[List[List[str]], Optional[str], Dict[str, Any]]:
        """Process a single PDF with memory-efficient approach"""
        metadata = {
            'filename': os.path.basename(file_path),
            'success': False,
            'error': None,
            'pages_processed': 0,
            'rows_extracted': 0
        }

        try:
            # Validate PDF first
            is_valid, error_msg, page_count = self.validate_pdf_structure(file_path)

            if not is_valid:
                metadata['error'] = error_msg
                return [], None, metadata

            # Extract date
            pdf_date = self.extract_date_from_pdf(file_path)
            date_str = pdf_date.strftime('%Y-%m-%d')

