    def process_pdfs_parallel(self, pdf_files: List[Path]) -> Tuple[List[List[str]], Dict[str, str]]:
        """Process multiple PDFs in parallel with optimized resource usage"""
        all_data = []
        date_file_map = {}

        print(f"Processing {len(pdf_files)} PDFs with {self.max_workers} workers...")

        # Group files into batches for better memory management
        batch_size = max(10, len(pdf_files) // (self.max_workers * 2))
        file_batches = [pdf_files[i:i + batch_size] for i in range(0, len(pdf_files), batch_size)]

        for batch_idx, file_batch in enumerate(file_batches, 1):
            print(f"Processing batch {batch_idx}/{len(file_batches)} ({len(file_batch)} files)...")

            # Use ProcessPoolExecutor for CPU-bound tasks
            with ProcessPoolExecutor(max_workers=self.max_workers) as executor:
                # Submit tasks for current batch
                future_to_file = {
                    executor.submit(self.process_single_pdf, str(pdf_file)): pdf_file 
                    for pdf_file in file_batch
                }

                # Process completed tasks
                batch_data = []
                for future in as_completed(future_to_file):
                    pdf_file = future_to_file[future]
                    filename = os.path.basename(str(pdf_file))

                    try:
                        data, date_str, metadata = future.result(timeout=180)  # 3 minute timeout

                        if metadata['success']:
                            if data:
                                batch_data.append(data)
                                if date_str:
                                    date_file_map[date_str] = filename
                            self.processed_count += 1
                            print(f"✓ {filename} - {metadata['rows_extracted']} rows")
                        else:
                            self.failed_count += 1
                            print(f"✗ {filename} - {metadata['error']}")

                    except TimeoutError:
                        self.failed_count += 1
                        print(f"⏰ Timeout: {filename}")
                    except Exception as e:
                        self.failed_count += 1
                        print(f"✗ Error: {filename} - {e}")

                # Add batch data to main collection
                for data_chunk in batch_data:
                    all_data.append(data_chunk)

                # Clear batch data to free memory
                del batch_data
                gc.collect()

        # Print summary
        print(f"\nProcessing Summary:")
        print(f"  Successful: {self.processed_count}")
        print(f"  Failed: {self.failed_count}")

        return all_data, date_file_map

    def analyze_data_structure(self, all_data: List[List[List[str]]]) -> int:
        """Analyze data structure efficiently using sampling"""
        if not all_data:
