#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
#include <unordered_map>

using Matrix = std::vector<std::vector<double>>;

class MinorCalculator {
    Matrix mat;
    size_t n;
    mutable std::unordered_map<size_t, double> cache;

    size_t hash_coords(size_t row, size_t col) const {
        return row * n + col;
    }

    Matrix create_minor(size_t row, size_t col) const {
        Matrix minor(n-1, std::vector<double>(n-1));
        for (size_t i = 0, mi = 0; i < n; ++i) {
            if (i == row) continue;
            for (size_t j = 0, mj = 0; j < n; ++j) {
                if (j == col) continue;
                minor[mi][mj++] = mat[i][j];
            }
            mi++;
        }
        return minor;
    }

    double determinant(const Matrix& m) const {
        const size_t size = m.size();
        if (size == 1) return m[0][0];
        if (size == 2) return m[0][0]*m[1][1] - m[0][1]*m[1][0];

        // LU decomposition for n ≥ 3
        Matrix LU = m;
        double det = 1.0;

        for (size_t k = 0; k < size; ++k) {
            // Partial pivoting
            auto max_it = std::max_element(LU.begin()+k, LU.end(),
                [k](const auto& a, const auto& b) {
                    return std::abs(a[k]) < std::abs(b[k]);
                });

            if (max_it->at(k) == 0) return 0; // Singular matrix

            if (std::distance(LU.begin(), max_it) != k) {
                std::iter_swap(LU.begin()+k, max_it);
                det *= -1;
            }

            // LU decomposition
            for (size_t i = k+1; i < size; ++i) {
                LU[i][k] /= LU[k][k];
                for (size_t j = k+1; j < size; ++j) {
                    LU[i][j] -= LU[i][k] * LU[k][j];
                }
            }
            det *= LU[k][k];
        }
        return det;
    }

public:
    MinorCalculator(const Matrix& matrix) : mat(matrix), n(matrix.size()) {}

    double minor_determinant(size_t row, size_t col) {
        auto key = hash_coords(row, col);
        if (cache.find(key) != cache.end()) return cache[key];

        if (n == 1) return 1.0;
        if (n == 2) return mat[1-row][1-col];

        auto minor = create_minor(row, col);
        return cache[key] = determinant(minor);
    }
};
